import http from 'http';
import fs from 'fs';
import path from 'path';
import os from 'os';
import { fileURLToPath } from 'url';
import { spawn } from 'child_process';
import { configManager } from '../core/config.js';
import { AntriAgent } from '../core/agent.js';
import { DialecticEngine } from '../core/dialectic.js';
import { GoalLoopEngine } from '../core/goalLoop.js';
import { SwarmEngine, SWARM_DEFAULT_NODES, SWARM_DEFAULT_EDGES } from '../core/swarm.js';
import { profileManager } from '../profiles/profileManager.js';
import { memoryManager } from '../memory/manager.js';
import { skillManager } from '../skills/skillManager.js';
import { SkillSynthesizer } from '../core/skillSynthesizer.js';
import { getAllActiveTools, ToolExecutor } from '../core/tools.js';
import { getAvailableModels } from '../providers/models.js';
import { PROMPT_TOOLKIT_COMMANDS } from '../cli/promptToolkit.js';
import { FilePickerService } from '../cli/dialogs/filePicker.js';
import { CodebaseBreather, ProjectContextCache } from '../core/codebaseBreather.js';
import chalk from 'chalk';
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
function getPublicDir() {
    const possiblePaths = [
        path.join(__dirname, 'public'),
        path.join(__dirname, '../../src/desktop/public'),
        path.join(process.cwd(), 'src/desktop/public'),
        path.join(process.cwd(), 'dist/desktop/public'),
    ];
    for (const p of possiblePaths) {
        if (fs.existsSync(p))
            return p;
    }
    return path.join(__dirname, 'public');
}
/**
 * Global Real-Time Desktop Permission Bridge
 * Allows CLI and Desktop to seamlessly share tool authorization dialogs.
 */
export class DesktopPermissionBridge {
    static sseClients = new Set();
    static pendingPermissions = new Map();
    static registerClient(sender) {
        this.sseClients.add(sender);
        return () => {
            this.sseClients.delete(sender);
        };
    }
    static hasActiveClients() {
        return this.sseClients.size > 0;
    }
    static requestPermission(name, args, source = 'cli') {
        const reqId = `perm_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
        for (const sender of this.sseClients) {
            try {
                sender('permission_request', {
                    requestId: reqId,
                    name,
                    args,
                    source,
                });
            }
            catch (_) { }
        }
        return new Promise((resolve) => {
            this.pendingPermissions.set(reqId, resolve);
            setTimeout(() => {
                if (this.pendingPermissions.has(reqId)) {
                    this.pendingPermissions.delete(reqId);
                    resolve(false);
                }
            }, 120000);
        });
    }
    static resolvePermission(requestId, allowed, alwaysAllow) {
        if (alwaysAllow) {
            configManager.setAlwaysAllow(true);
        }
        const resolver = this.pendingPermissions.get(requestId);
        if (resolver) {
            this.pendingPermissions.delete(requestId);
            resolver(allowed);
            for (const sender of this.sseClients) {
                try {
                    sender('permission_resolved', { requestId, allowed });
                }
                catch (_) { }
            }
            return true;
        }
        return false;
    }
}
export class DesktopServer {
    server = null;
    port = parseInt(process.env.PORT || '3456', 10);
    activeAgent;
    currentSseSender = null;
    constructor() {
        this.activeAgent = new AntriAgent(configManager.get());
        this.setupPermissionHandler();
    }
    setupPermissionHandler() {
        this.activeAgent.getToolExecutor().setPermissionHandler(async (name, args) => {
            const cfg = configManager.get();
            if (cfg.alwaysAllow)
                return true;
            if (!ToolExecutor.isSensitive(name))
                return true;
            return DesktopPermissionBridge.requestPermission(name, args, 'desktop');
        });
    }
    async start() {
        const publicDir = getPublicDir();
        return new Promise((resolve, reject) => {
            this.server = http.createServer(async (req, res) => {
                // Enable CORS
                res.setHeader('Access-Control-Allow-Origin', '*');
                res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
                res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
                if (req.method === 'OPTIONS') {
                    res.writeHead(204);
                    res.end();
                    return;
                }
                const url = new URL(req.url || '/', `http://localhost:${this.port}`);
                const pathname = url.pathname;
                // 1. API Endpoints
                if (pathname.startsWith('/api/')) {
                    await this.handleApi(pathname, url, req, res);
                    return;
                }
                // Pure Backend API Mode: When deployed as a backend service, return API info instead of HTML
                if (pathname === '/' && (process.env.ANTRI_BACKEND_ONLY === 'true' || process.env.BACKEND_ONLY === 'true')) {
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({
                        status: 'online',
                        service: 'ANTRI Code Google Cloud Run Backend API',
                        version: configManager.get().version,
                        provider: configManager.get().provider || 'gemini',
                        model: configManager.get().model || 'gemini-3.5-flash',
                        framework: '@google/genai (Google GenAI SDK)',
                        platform: 'Google Cloud Run',
                        endpoints: {
                            health: 'GET /api/health',
                            status: 'GET /api/status',
                            models: 'GET /api/models',
                            commands: 'GET /api/commands',
                            chatStream: 'POST /api/chat',
                            bugTwinReproduce: 'POST /api/bugtwin/reproduce',
                            crashZeroReplay: 'POST /api/crashzero/replay',
                            dialecticDebate: 'POST /api/debate',
                            goalLoop: 'POST /api/goal',
                        },
                        documentation: 'https://github.com/ashu90-prog/antri_cli',
                    }, null, 2));
                    return;
                }
                // 2. Static File Serving (Desktop & Web Control Plane)
                let filePath = path.join(publicDir, pathname === '/' ? 'index.html' : pathname);
                if (!fs.existsSync(filePath)) {
                    filePath = path.join(publicDir, 'index.html');
                }
                const ext = path.extname(filePath).toLowerCase();
                const contentTypes = {
                    '.html': 'text/html; charset=utf-8',
                    '.css': 'text/css; charset=utf-8',
                    '.js': 'application/javascript; charset=utf-8',
                    '.json': 'application/json',
                    '.png': 'image/png',
                    '.svg': 'image/svg+xml',
                    '.jpg': 'image/jpeg',
                    '.jpeg': 'image/jpeg',
                    '.webp': 'image/webp',
                };
                try {
                    const data = fs.readFileSync(filePath);
                    res.writeHead(200, { 'Content-Type': contentTypes[ext] || 'text/plain' });
                    res.end(data);
                }
                catch {
                    res.writeHead(404);
                    res.end('Not Found');
                }
            });
            this.server.listen(this.port, () => {
                resolve(this.port);
            });
            this.server.on('error', (err) => {
                if (err.code === 'EADDRINUSE') {
                    this.port += 1;
                    this.server?.listen(this.port);
                }
                else {
                    reject(err);
                }
            });
        });
    }
    async stop() {
        return new Promise((resolve) => {
            if (this.server) {
                this.server.close(() => resolve());
            }
            else {
                resolve();
            }
        });
    }
    async handleApi(pathname, url, req, res) {
        const config = configManager.get();
        // GET /api/health (Google Cloud Run probe & verification endpoint)
        if (pathname === '/api/health' && req.method === 'GET') {
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                status: 'healthy',
                service: 'antri_backend',
                version: config.version,
                provider: config.provider,
                model: config.model,
                googleCloud: {
                    platform: 'Google Cloud Run',
                    project: process.env.GOOGLE_CLOUD_PROJECT || process.env.GCP_PROJECT || 'antri-agentic-hackathon',
                    framework: '@google/genai (Google GenAI SDK)',
                    modelFamily: 'Gemini 3.7 / 3.5 Suite',
                    region: process.env.K_SERVICE ? 'cloud-run-managed' : 'local-node',
                },
                uptime: process.uptime(),
            }));
            return;
        }
        // GET /api/status
        if (pathname === '/api/status' && req.method === 'GET') {
            const { AuthManager } = await import('../cloud/auth.js');
            const currentUser = AuthManager.getCurrentUser();
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                config,
                activeProfile: profileManager.getActiveProfileName(),
                toolsCount: getAllActiveTools().length,
                user: currentUser,
            }));
            return;
        }
        // GET /api/auth/user
        if (pathname === '/api/auth/user' && req.method === 'GET') {
            const { AuthManager } = await import('../cloud/auth.js');
            const user = AuthManager.getCurrentUser();
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ user }));
            return;
        }
        // GET /api/commands (Prompt Toolkit Slash Commands)
        if (pathname === '/api/commands' && req.method === 'GET') {
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ success: true, commands: PROMPT_TOOLKIT_COMMANDS }));
