let paletteSelectedIndex = 0;
let activePaletteMode = null; // 'slash' | 'file' | null

// Skills State
let allSkillsList = [];
let selectedSkillId = null;
let currentSkillCategory = 'all';
let skillSearchQuery = '';

// Initialize on Load
